import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Parcela } from '../../parcelas/entities/parcela.entity';
import { Cultivador } from '../../cultivadores/entities/cultivador.entity';

@Injectable()
export class AsignarCultivadorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Parcela) private readonly parcelas: Repository<Parcela>,
    @InjectRepository(Cultivador) private readonly cultivadores: Repository<Cultivador>
  ) {}

  buscarParcelaRepository(parcelaId: number) {
    return this.parcelas.findOneBy({ id: parcelaId });
  }

  buscarCultivadorRepository(cultivadorId: number) {
    return this.cultivadores.findOneBy({ id: cultivadorId });
  }

  async asignarCultivadorRepository(parcelaId: number, cultivadorId: number, rol: string) {
    const asignacion = { parcelaId, cultivadorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarCultivadorRepository } from './repository';

@Injectable()
export class AsignarCultivadorService {
  constructor(private readonly repository: AsignarCultivadorRepository) {}

  async asignarCultivadorService(parcelaId: number, cultivadorId: number, rol: string) {
    const parcela = await this.repository.buscarParcelaRepository(parcelaId);
    const cultivador = await this.repository.buscarCultivadorRepository(cultivadorId);
    if (!parcela || !cultivador) {
      throw new NotFoundException('No existe la parcela o el cultivador');
    }

    try {
      return await this.repository.asignarCultivadorRepository(parcelaId, cultivadorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El cultivador ya está asignado a esa parcela');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarCultivadorService } from './service';

@Controller('parcelas/:parcelaId/asignaciones')
export class AsignarCultivadorController {
  constructor(private readonly service: AsignarCultivadorService) {}

  @Post()
  asignar(@Param('parcelaId') parcelaId: string, @Body() datos: { cultivadorId: number; rol: string }) {
    return this.service.asignarCultivadorService(Number(parcelaId), datos.cultivadorId, datos.rol);
  }
}
